// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/endpoints", wrapper.ListWebhookEndpoints)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/endpoints", wrapper.CreateWebhookEndpoint)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}", wrapper.DeleteWebhookEndpoint)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}", wrapper.GetWebhookEndpoint)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}", wrapper.UpdateWebhookEndpoint)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}/verification", wrapper.VerifyWebhookEndpoint)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}/secret-rotations", wrapper.RotateWebhookEndpointSecret)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}/disable", wrapper.DisableWebhookEndpoint)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}/test-events", wrapper.SendWebhookTestEvent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/deliveries", wrapper.ListWebhookDeliveries)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/deliveries/{deliveryId}", wrapper.GetWebhookDelivery)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/deliveries/{deliveryId}/replays", wrapper.ReplayWebhookDelivery)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/webhooks/tenants/{tenantId}/reports/daily-activity", wrapper.GetDailyActivity)
	})

	return r
}

