// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListWebhookDeliveries The delivery log
	// (GET /v1/webhooks/tenants/{tenantId}/deliveries)
	ListWebhookDeliveries(ctx context.Context, request ListWebhookDeliveriesRequestObject) (ListWebhookDeliveriesResponseObject, error)
	// GetWebhookDelivery One delivery, its body and every attempt
	// (GET /v1/webhooks/tenants/{tenantId}/deliveries/{deliveryId})
	GetWebhookDelivery(ctx context.Context, request GetWebhookDeliveryRequestObject) (GetWebhookDeliveryResponseObject, error)
	// ReplayWebhookDelivery Send a delivery again
	// (POST /v1/webhooks/tenants/{tenantId}/deliveries/{deliveryId}/replays)
	ReplayWebhookDelivery(ctx context.Context, request ReplayWebhookDeliveryRequestObject) (ReplayWebhookDeliveryResponseObject, error)
	// ListWebhookEndpoints The account's webhook endpoints
	// (GET /v1/webhooks/tenants/{tenantId}/endpoints)
	ListWebhookEndpoints(ctx context.Context, request ListWebhookEndpointsRequestObject) (ListWebhookEndpointsResponseObject, error)
	// CreateWebhookEndpoint Register a webhook endpoint
	// (POST /v1/webhooks/tenants/{tenantId}/endpoints)
	CreateWebhookEndpoint(ctx context.Context, request CreateWebhookEndpointRequestObject) (CreateWebhookEndpointResponseObject, error)
	// DeleteWebhookEndpoint Delete an endpoint
	// (DELETE /v1/webhooks/tenants/{tenantId}/endpoints/{endpointId})
	DeleteWebhookEndpoint(ctx context.Context, request DeleteWebhookEndpointRequestObject) (DeleteWebhookEndpointResponseObject, error)
	// GetWebhookEndpoint One webhook endpoint
	// (GET /v1/webhooks/tenants/{tenantId}/endpoints/{endpointId})
	GetWebhookEndpoint(ctx context.Context, request GetWebhookEndpointRequestObject) (GetWebhookEndpointResponseObject, error)
	// UpdateWebhookEndpoint Change an endpoint's URL, description or events
	// (PATCH /v1/webhooks/tenants/{tenantId}/endpoints/{endpointId})
	UpdateWebhookEndpoint(ctx context.Context, request UpdateWebhookEndpointRequestObject) (UpdateWebhookEndpointResponseObject, error)
	// DisableWebhookEndpoint Stop sending to an endpoint
	// (POST /v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}/disable)
	DisableWebhookEndpoint(ctx context.Context, request DisableWebhookEndpointRequestObject) (DisableWebhookEndpointResponseObject, error)
	// RotateWebhookEndpointSecret Give the endpoint a new signing secret
	// (POST /v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}/secret-rotations)
	RotateWebhookEndpointSecret(ctx context.Context, request RotateWebhookEndpointSecretRequestObject) (RotateWebhookEndpointSecretResponseObject, error)
	// SendWebhookTestEvent Send the endpoint a test event
	// (POST /v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}/test-events)
	SendWebhookTestEvent(ctx context.Context, request SendWebhookTestEventRequestObject) (SendWebhookTestEventResponseObject, error)
	// VerifyWebhookEndpoint Send the verification challenge
	// (POST /v1/webhooks/tenants/{tenantId}/endpoints/{endpointId}/verification)
	VerifyWebhookEndpoint(ctx context.Context, request VerifyWebhookEndpointRequestObject) (VerifyWebhookEndpointResponseObject, error)
	// GetDailyActivity The account's wallet activity per day
	// (GET /v1/webhooks/tenants/{tenantId}/reports/daily-activity)
	GetDailyActivity(ctx context.Context, request GetDailyActivityRequestObject) (GetDailyActivityResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

